const today = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Kolkata',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).format(new Date());

const executedAtIST = new Intl.DateTimeFormat('sv-SE', {
  timeZone: 'Asia/Kolkata',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: false,
}).format(new Date()) + ' IST';

function toUtcMs(isoDate) {
  if (!isoDate || !/^\d{4}-\d{2}-\d{2}$/.test(String(isoDate).trim())) return null;
  const [y, m, d] = String(isoDate).trim().split('-').map(Number);
  return Date.UTC(y, m - 1, d);
}

const todayMs = toUtcMs(today);
const results = [];

for (const item of $input.all()) {
  const r = item.json || {};
  const memberId = String(r.member_id || '').trim();
  const phone = String(r.phone || '').replace(/\D/g, '');
  const email = String(r.email || '').trim().toLowerCase() || 'member@crushfitness.in';
  const expiryMs = toUtcMs(r.expiry_date);
  const startMs = toUtcMs(r.start_date);

  if (!memberId || (!phone && !email) || expiryMs === null) continue;
  if (String(r.last_reminder_date || '').trim() === today) continue;
  if (String(r.member_status || '').trim() === 'Frozen') continue;

  const daysUntilExpiry = Math.round((expiryMs - todayMs) / 86400000);
  const daysSinceStart = startMs !== null ? Math.round((todayMs - startMs) / 86400000) : null;
  const paymentStatus = String(r.payment_status || '').trim();
  const name = String(r.name || 'Member').trim();

  let followupType = null;
  let templateName = 'crush_fitness_followup_email';
  let emailSubject = '';
  let messagePreview = '';

  if (daysUntilExpiry === 0) {
    followupType = 'EXPIRY_T0_FINAL';
    emailSubject = '[Crush Lifestyle Fitness Studio] Action Required: Your Membership Expires Today';
    messagePreview = `Hi ${name}, your ${r.plan} membership at Crush Lifestyle Fitness Studio expires TODAY (${r.expiry_date}). Renew at the front desk or via UPI to keep your workout streak unbroken!`;
  } else if (daysUntilExpiry === 3) {
    followupType = 'EXPIRY_T3_URGENT';
    emailSubject = `[Crush Lifestyle Fitness Studio] 3 Days Left on Your ${r.plan} Membership`;
    messagePreview = `Hi ${name}, 3 days left on your ${r.plan} plan (expires ${r.expiry_date}). Renew now to avoid access interruption.`;
  } else if (daysUntilExpiry === 7) {
    followupType = 'EXPIRY_T7_EARLY_BIRD';
    emailSubject = `[Crush Lifestyle Fitness Studio] Your Membership Expires in 7 Days (${r.expiry_date})`;
    messagePreview = `Hi ${name}, your Crush Lifestyle Fitness Studio membership expires in 7 days (${r.expiry_date}). Renew early for priority trainer slot booking.`;
  } else if (paymentStatus === 'Pending' && daysSinceStart !== null && [1, 3, 7].includes(daysSinceStart)) {
    followupType = 'PAYMENT_PENDING_FOLLOWUP';
    emailSubject = `[Crush Lifestyle Fitness Studio] Friendly Reminder: Pending Fee Rs.${r.fee}`;
    messagePreview = `Hi ${name}, friendly reminder that your ${r.plan} membership fee of Rs.${r.fee} is pending. Please clear your dues at reception or request a Razorpay link.`;
  } else if (daysUntilExpiry === -3) {
    followupType = 'WINBACK_EXPIRED_T3';
    emailSubject = `[Crush Lifestyle Fitness Studio] We Miss You, ${name}! Zero Re-Joining Fee Offer`;
    messagePreview = `We miss you at Crush Lifestyle Fitness Studio, ${name}! Your membership expired 3 days ago (${r.expiry_date}). Restart today with zero re-joining fee.`;
  } else if (daysUntilExpiry === -14) {
    followupType = 'WINBACK_EXPIRED_T14';
    emailSubject = '[Crush Lifestyle Fitness Studio] Complimentary Personal Training Assessment Waiting for You';
    messagePreview = `Hi ${name}, it has been 2 weeks since your plan expired. Come back to Crush Lifestyle Fitness Studio for a complimentary personal-training assessment!`;
  } else if (daysSinceStart === 3) {
    followupType = 'ONBOARDING_DAY_3';
    emailSubject = `[Crush Lifestyle Fitness Studio] Welcome to Day 3, ${name}!`;
    messagePreview = `Welcome to Day 3 at Crush Lifestyle Fitness Studio, ${name}! How are your workouts going? Reply to book your complimentary form & goal check-in.`;
  }

  if (!followupType) continue;

  const emailHtml = `<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;padding:20px;border:1px solid #e5e7eb;border-radius:8px;"><h2 style="margin:0 0 12px;color:#111827;">Crush Lifestyle Fitness Studio</h2><p style="font-size:15px;line-height:1.6;color:#1f2937;">${messagePreview}</p><p style="font-size:13px;color:#4b5563;background:#f9fafb;padding:10px 12px;border-radius:6px;"><strong>Member ID:</strong> ${memberId} &nbsp;|&nbsp; <strong>Plan:</strong> ${r.plan} &nbsp;|&nbsp; <strong>Expiry:</strong> ${r.expiry_date}</p><p style="font-size:12px;color:#6b7280;margin-top:16px;">Reply to this email or visit the front desk for instant renewal assistance.</p></div>`;

  const newMemberStatus = daysUntilExpiry < 0 ? 'Expired' : (String(r.member_status || '').trim() || 'Active');
  const existingNotes = String(r.notes || '').trim();
  const auditTag = `[${today}] ${followupType}`;
  const updatedNotes = existingNotes ? `${existingNotes} | ${auditTag}` : auditTag;

  results.push({
    json: {
      log_id: `LOG-${Date.now().toString(36).toUpperCase().slice(-6)}-${results.length + 1}`,
      member_id: memberId,
      name,
      phone,
      email,
      plan: r.plan,
      fee: r.fee,
      start_date: r.start_date,
      expiry_date: r.expiry_date,
      payment_status: paymentStatus,
      followup_type: followupType,
      template_name: templateName,
      email_subject: emailSubject,
      email_html: emailHtml,
      message_preview: messagePreview,
      new_member_status: newMemberStatus,
      last_reminder_date: today,
      executed_at_ist: executedAtIST,
      notes_update: updatedNotes,
    },
  });
}

return results;
